def count_weights(a):
    n = len(a)
    result = 0
    for i in range(n):
        count = {}
        for j in range(i, n):
            count[a[j]] = count.get(a[j], 0) + 1
            pairs = 0
            for value in count:
                pairs += count[value] * (count[value] - 1) // 2
            result += pairs
    return result

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        print(count_weights(a))

if __name__ == "__main__":
    main()
